if (n == 0) {
    return block{nullptr, 0};
}

const size_t aligned_length = (n + alignment - 1) & ~(alignment - 1);
const size_t current_offset = p - data;
const size_t aligned_offset = (current_offset + alignment - 1) & ~(alignment - 1);
const size_t required_space = aligned_offset - current_offset + aligned_length;

if (required_space > max_size || aligned_offset + aligned_length > max_size) {
    return block{nullptr, 0};
}

char* aligned_ptr = data + aligned_offset;
block result{aligned_ptr, aligned_length};
p = aligned_ptr + aligned_length;
return result;

